<style lang="scss" src="./send-message-modal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import ScrollView from "../scroll-view/scroll-view";
import { MountingPortal } from "portal-vue";
import IconButton from "../icon-button/icon-button.vue";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import Button from "../button/button";
import { has } from "../../util/has";
import {
  SendMessageModalMode,
  SendMessageModalModeValues,
} from "./send-message-modal.constants";

/**
 * This is a modal component for sending a message
 */
@Component({
  components: {
    Button,
    ScrollView,
    MountingPortal,
    IconButton,
    Icon,
  },
})
export default class SendMessageModal extends Vue {
  /** Rendering mode for this component */
  @Prop({
    type: String,
    default: SendMessageModalMode.MESSAGE,
    validator: has(SendMessageModalModeValues),
  })
  mode;
  /** Name of the person the message is being sent to */
  @Prop({ type: String }) to;
  /** Buttons to appear under the metrics in the banner */
  @Prop({ type: Array, default: () => [] }) buttons;
  /** Values used to pre-populate the message. Format matches modal output */
  @Prop({ type: Object, default: () => ({}) }) defaultEmailData;

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;
  title = "";
  message = "";
  emailTo = "";
  emailFrom = "";
  emailSubject = "";
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  mounted() {
    this.emailFrom = this.defaultEmailData.emailFrom || "";
    this.emailTo = this.defaultEmailData.emailTo || "";
    this.emailSubject = this.defaultEmailData.emailSubject || "";
    this.message = this.defaultEmailData.message || "";
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  get isEmail() {
    return this.mode === SendMessageModalMode.EMAIL;
  }

  get isInternalMessage() {
    return this.mode === SendMessageModalMode.INTERNAL_MESSAGE;
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    /**
     * Emits when the user requests the dialogue be closed.
     *
     * @event close
     */
    this.$emit("close");
    e.stopPropagation();
    e.preventDefault();
  }

  handleClose() {
    this.$emit("close");
  }

  handleDiscard() {
    /**
     * Emits when the user elects to discard the message rather than send
     *
     * @event discard
     */
    this.$emit("discard");
  }

  handleResize() {
    this.$forceUpdate();
  }

  handleClick(index) {
    /**
     * Fires when you click on a button. This fires the event with the index of
     * the button clicked which corresponds to the buttons prop.
     *
     * The second argument contains all of the form data currently in the modal.
     *
     * @event click {number, object}
     */
    this.$emit("click", index, {
      emailTo: this.emailTo,
      emailFrom: this.emailFrom,
      emailSubject: this.emailSubject,
      message: this.message,
    });
  }

  createFile(file) {
    if (!file.type.match("image.*")) {
      alert("Select an image");
      return;
    }
    const reader = new FileReader();
    const vm = this;

    reader.onload = function(e) {
      vm.image = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="SendMessageModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <div class="SendMessageModal__Body">
        <div class="SendMessageModal__Head">
          <div class="SendMessageModal__HeadTitle">
            <span>Send a message to</span>
            <h2>{{ to }}</h2>
          </div>
          <div class="SendMessageModal__Close" @click="handleClose">
            <Icon
              :shape="IconShape.CLOSE"
              :color="'rgba(2, 0, 38, 0.3)'"
              :size="12"
            />
          </div>
        </div>
        <div class="SendMessageModal__Content">
          <div v-if="isEmail || isInternalMessage" class="SendMessageModal__EmailHead">
            <div v-if="isEmail" class="SendMessageModal__EmailRow">
              <div v-if="isEmail" class="SendMessageModal__EmailTitle">To</div>
              <input class="SendMessageModal__EmailInput" v-model="emailTo" />
            </div>
            <div v-if="isEmail" class="SendMessageModal__EmailRow">
              <div v-if="isEmail" class="SendMessageModal__EmailTitle">
                From
              </div>
              <input class="SendMessageModal__EmailInput" v-model="emailFrom" />
            </div>
            <div v-if="isEmail || isInternalMessage" class="SendMessageModal__EmailRow">
              <div v-if="isEmail || isInternalMessage" class="SendMessageModal__EmailTitle">
                Subject
              </div>
              <input
                class="SendMessageModal__EmailInput"
                v-model="emailSubject"
              />
            </div>
          </div>
          <div v-if="isEmail" class="SendMessageModal__MessageTitle">
            Your Message
          </div>
          <textarea class="SendMessageModal__MessageBody" v-model="message" />
          <div class="SendMessageModal__Buttons">
            <div
              class="SendMessageModal__Button"
              v-for="(button, i) in buttons"
              :key="i"
            >
              <Button
                @click="handleClick(i)"
                :mode="button.mode"
                :label="button.label"
                :size="button.size"
                :mobileStretch="true"
              />
            </div>
          </div>
          <div class="SendMessageModal__Discard" @click="handleDiscard">
            <span>Discard</span>
          </div>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
